from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def replace_once(path: Path, old: str, new: str) -> None:
    text = path.read_text(encoding="utf-8")
    if old not in text:
        raise SystemExit(f"Expected block not found in {path}: {old[:120]!r}")
    path.write_text(text.replace(old, new, 1), encoding="utf-8")

xaml = ROOT / "src/BPSRStreamKit/MainWindow.xaml"
replace_once(xaml,
'''                        <Border Background="#14231D" BorderBrush="#28503F" BorderThickness="1" CornerRadius="18" Padding="12,7" Margin="0,0,8,0">\n                            <StackPanel Orientation="Horizontal">\n                                <Ellipse Width="7" Height="7" Fill="{StaticResource GoodBrush}" VerticalAlignment="Center"/>\n                                <TextBlock Text="Beginner mode" FontSize="11" Foreground="#BFE9D3" Margin="7,0,0,0"/>\n                            </StackPanel>\n                        </Border>\n''', "")
text = xaml.read_text(encoding="utf-8").replace('Text="v2.0.0"', 'Text="v2.0.2"').replace('Text="v2.0.1"', 'Text="v2.0.2"')
xaml.write_text(text, encoding="utf-8")

