replace_once(auto,
'''    private async Task<bool> HasTransparentVTubeFrameAsync()\n    {\n''',
'''    private async Task AutoFitVTubeStudioAvatarAsync()\n    {\n        var screenshot = await WithSessionAsync(s => s.RequestAsync("GetSourceScreenshot", new JsonObject\n        { ["sourceName"] = VTubeInputName, ["imageFormat"] = "png", ["imageWidth"] = 320, ["imageHeight"] = 180 }));\n        var imageData = screenshot?["imageData"]?.GetValue<string>();\n        if (string.IsNullOrWhiteSpace(imageData) || !TryGetVisibleBounds(imageData, out var left, out var top, out var right, out var bottom)) return;\n        await WithSessionAsync(async session =>\n        {\n            foreach (var sceneName in VTubeHorizontalScenes)\n            {\n                try\n                {\n                    var itemsResponse = await session.RequestAsync("GetSceneItemList", new JsonObject { ["sceneName"] = sceneName });\n                    var item = itemsResponse?["sceneItems"]?.AsArray()?.OfType<JsonObject>().FirstOrDefault(x => string.Equals(x["sourceName"]?.GetValue<string>(), VTubeInputName, StringComparison.Ordinal));\n                    var sceneItemId = item?["sceneItemId"]?.GetValue<int>() ?? 0; if (sceneItemId <= 0) continue;\n                    var transformResponse = await session.RequestAsync("GetSceneItemTransform", new JsonObject { ["sceneName"] = sceneName, ["sceneItemId"] = sceneItemId });\n                    var transform = transformResponse?["sceneItemTransform"]?.AsObject();\n                    var sourceWidth = transform?["sourceWidth"]?.GetValue<double>() ?? 1920.0; var sourceHeight = transform?["sourceHeight"]?.GetValue<double>() ?? 1080.0;\n                    if (sourceWidth <= 0) sourceWidth = 1920.0; if (sourceHeight <= 0) sourceHeight = 1080.0;\n                    var cropLeft = Math.Clamp(left * sourceWidth, 0, Math.Max(0, sourceWidth - 2));\n                    var cropTop = Math.Clamp(top * sourceHeight, 0, Math.Max(0, sourceHeight - 2));\n                    var cropRight = Math.Clamp((1.0 - right) * sourceWidth, 0, Math.Max(0, sourceWidth - cropLeft - 2));\n                    var cropBottom = Math.Clamp((1.0 - bottom) * sourceHeight, 0, Math.Max(0, sourceHeight - cropTop - 2));\n                    await session.RequestAsync("SetSceneItemTransform", new JsonObject\n                    {\n                        ["sceneName"] = sceneName, ["sceneItemId"] = sceneItemId,\n                        ["sceneItemTransform"] = new JsonObject\n                        {\n                            ["positionX"] = 20.0, ["positionY"] = 490.0, ["alignment"] = 5,\n                            ["cropLeft"] = cropLeft, ["cropTop"] = cropTop, ["cropRight"] = cropRight, ["cropBottom"] = cropBottom,\n                            ["boundsType"] = "OBS_BOUNDS_SCALE_INNER", ["boundsAlignment"] = 5, ["boundsWidth"] = 520.0, ["boundsHeight"] = 570.0\n                        }\n                    });\n                    await session.RequestAsync("SetSceneItemEnabled", new JsonObject { ["sceneName"] = sceneName, ["sceneItemId"] = sceneItemId, ["sceneItemEnabled"] = true });\n                }\n                catch { }\n            }\n            return true;\n        });\n    }\n\n    private static bool TryGetVisibleBounds(string dataUri, out double left, out double top, out double right, out double bottom)\n    {\n        left = 0; top = 0; right = 1; bottom = 1;\n        try\n        {\n            var comma = dataUri.IndexOf(','); var base64 = comma >= 0 ? dataUri[(comma + 1)..] : dataUri; var bytes = Convert.FromBase64String(base64);\n            using var stream = new MemoryStream(bytes); var decoder = BitmapDecoder.Create(stream, BitmapCreateOptions.PreservePixelFormat, BitmapCacheOption.OnLoad); if (decoder.Frames.Count == 0) return false;\n            var bitmap = new FormatConvertedBitmap(decoder.Frames[0], PixelFormats.Bgra32, null, 0); var width = bitmap.PixelWidth; var height = bitmap.PixelHeight; if (width <= 0 || height <= 0) return false;\n            var stride = width * 4; var pixels = new byte[stride * height]; bitmap.CopyPixels(pixels, stride, 0);\n            var minX = width; var minY = height; var maxX = -1; var maxY = -1; var visible = 0;\n            for (var y = 0; y < height; y++) for (var x = 0; x < width; x++)\n            {\n                var alpha = pixels[(y * stride) + (x * 4) + 3]; if (alpha <= 18) continue; visible++; minX = Math.Min(minX, x); maxX = Math.Max(maxX, x); minY = Math.Min(minY, y); maxY = Math.Max(maxY, y);\n            }\n            if (visible < 20 || maxX < minX || maxY < minY) return false;\n            var padX = Math.Max(3, (int)Math.Round((maxX - minX + 1) * 0.06)); var padY = Math.Max(3, (int)Math.Round((maxY - minY + 1) * 0.04));\n            minX = Math.Max(0, minX - padX); maxX = Math.Min(width - 1, maxX + padX); minY = Math.Max(0, minY - padY); maxY = Math.Min(height - 1, maxY + padY);\n            left = (double)minX / width; top = (double)minY / height; right = (double)(maxX + 1) / width; bottom = (double)(maxY + 1) / height;\n            return right - left > 0.02 && bottom - top > 0.02;\n        }\n        catch { return false; }\n    }\n\n    private async Task<bool> HasTransparentVTubeFrameAsync()\n    {\n''')
